using BARANG.Core.Domain.Quality;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BARANG.Core.Infrastructure.Persistence.Configurations;
internal static class QualityConfig{internal static void Base<T>(EntityTypeBuilder<T>b,string table)where T:class{b.ToTable(table);b.HasKey("Id");b.Property<Guid>("Id").HasColumnName("id");b.Property<Guid>("CompanyId").HasColumnName("company_id");}}
internal sealed class QCTemplateConfiguration:IEntityTypeConfiguration<QCChecklistTemplate>{public void Configure(EntityTypeBuilder<QCChecklistTemplate>b){QualityConfig.Base(b,"qc_templates");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(80);b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(200);b.Property(x=>x.ApplicableJobType).HasColumnName("applicable_job_type").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ProductTypeCode).HasColumnName("product_type_code").HasMaxLength(50);b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.Code}).IsUnique();}}
internal sealed class QCCriterionConfiguration:IEntityTypeConfiguration<QCChecklistCriterion>{public void Configure(EntityTypeBuilder<QCChecklistCriterion>b){QualityConfig.Base(b,"qc_template_criteria");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.TemplateId).HasColumnName("template_id");b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(80);b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(200);b.Property(x=>x.CriterionType).HasColumnName("criterion_type").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.IsRequired).HasColumnName("is_required");b.Property(x=>x.SortOrder).HasColumnName("sort_order");b.Property(x=>x.MinimumValue).HasColumnName("minimum_value").HasPrecision(18,4);b.Property(x=>x.MaximumValue).HasColumnName("maximum_value").HasPrecision(18,4);b.Property(x=>x.AllowedChoiceCodes).HasColumnName("allowed_choice_codes").HasMaxLength(1000);b.HasIndex(x=>new{x.CompanyId,x.TemplateId,x.Code}).IsUnique();b.HasOne<QCChecklistTemplate>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.TemplateId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class QCInspectionConfiguration:IEntityTypeConfiguration<QCInspection>{public void Configure(EntityTypeBuilder<QCInspection>b){QualityConfig.Base(b,"qc_inspections");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.ProductionJobId).HasColumnName("production_job_id");b.Property(x=>x.TemplateId).HasColumnName("template_id");b.Property(x=>x.TemplateVersion).HasColumnName("template_version");b.Property(x=>x.InspectorUserId).HasColumnName("inspector_user_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(25);b.Property(x=>x.Outcome).HasColumnName("outcome").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.ParentInspectionId).HasColumnName("parent_inspection_id");b.Property(x=>x.ReproductionRequestId).HasColumnName("reproduction_request_id");b.Property(x=>x.StartedAtUtc).HasColumnName("started_at_utc");b.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at_utc");b.Property(x=>x.DecisionReason).HasColumnName("decision_reason").HasMaxLength(500);b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(1000);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.ProductionJobId}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.Status,x.CreatedAtUtc});b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Orders.OrderItem>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderItemId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Production.ProductionJob>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductionJobId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<QCChecklistTemplate>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.TemplateId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<QCInspection>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ParentInspectionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class QCResultConfiguration:IEntityTypeConfiguration<QCCriteriaResult>{public void Configure(EntityTypeBuilder<QCCriteriaResult>b){QualityConfig.Base(b,"qc_criteria_results");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.InspectionId).HasColumnName("inspection_id");b.Property(x=>x.TemplateCriterionId).HasColumnName("template_criterion_id");b.Property(x=>x.CriterionCode).HasColumnName("criterion_code").HasMaxLength(80);b.Property(x=>x.CriterionName).HasColumnName("criterion_name").HasMaxLength(200);b.Property(x=>x.CriterionType).HasColumnName("criterion_type").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.IsRequired).HasColumnName("is_required");b.Property(x=>x.PassFailValue).HasColumnName("pass_fail_value");b.Property(x=>x.NumericValue).HasColumnName("numeric_value").HasPrecision(18,4);b.Property(x=>x.TextValue).HasColumnName("text_value").HasMaxLength(1000);b.Property(x=>x.ChoiceCode).HasColumnName("choice_code").HasMaxLength(80);b.Property(x=>x.RecordedAtUtc).HasColumnName("recorded_at_utc");b.Property(x=>x.RecordedByUserId).HasColumnName("recorded_by_user_id");b.HasIndex(x=>new{x.CompanyId,x.InspectionId,x.TemplateCriterionId}).IsUnique();b.HasOne<QCInspection>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.InspectionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<QCChecklistCriterion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.TemplateCriterionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class DefectTypeConfiguration:IEntityTypeConfiguration<DefectType>{public void Configure(EntityTypeBuilder<DefectType>b){QualityConfig.Base(b,"defect_types");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(80);b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(200);b.Property(x=>x.CategoryCode).HasColumnName("category_code").HasMaxLength(50);b.Property(x=>x.Severity).HasColumnName("severity").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.IsBlocking).HasColumnName("is_blocking");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.Code}).IsUnique();}}
